package ledger

import (
	"errors"
	"fmt"
	"sort"
	"strconv"
	"strings"
)

// Refactor log:
//  1. Replaced the hand-rolled bubble sort with sort.Slice on a copy of the
//     entries, keyed by (Date, Description, Change).
//  2. Replaced the goroutine-per-entry channel fan-out with a simple sequential
//     loop over the sorted entries.
//  3. Extracted the duplicated amount formatting into formatAmount, which
//     handles currency symbol, digit grouping, decimal separator, and
//     negative-number style per locale.
//  4. Moved currency and locale validation to the top of FormatLedger so it
//     happens before any formatting (the old code validated the locale via the
//     header and the currency only inside the worker goroutines, and used a
//     recursive call for the empty-ledger case).
//  5. Extracted date validation/formatting into formatDate.
//  6. Replaced the rune-counting loop with len for ASCII-only output.

type Entry struct {
	Date        string // "Y-m-d"
	Description string
	Change      int // in cents
}

func FormatLedger(currency string, locale string, entries []Entry) (string, error) {
	if _, ok := currencySymbols[currency]; !ok {
		return "", errors.New("invalid currency")
	}
	if _, ok := locales[locale]; !ok {
		return "", errors.New("invalid locale")
	}

	sorted := make([]Entry, len(entries))
	copy(sorted, entries)
	sort.Slice(sorted, func(i, j int) bool {
		if sorted[i].Date != sorted[j].Date {
			return sorted[i].Date < sorted[j].Date
		}
		if sorted[i].Description != sorted[j].Description {
			return sorted[i].Description < sorted[j].Description
		}
		return sorted[i].Change < sorted[j].Change
	})

	var b strings.Builder
	b.WriteString(header(locale) + "\n")
	for _, entry := range sorted {
		date, err := formatDate(locale, entry.Date)
		if err != nil {
			return "", err
		}
		b.WriteString(date + " | " + pad(entry.Description, 25) + " | " +
			rightPad(formatAmount(currency, locale, entry.Change), 13) + "\n")
	}
	return b.String(), nil
}
```

