func formatAmount(currency, locale string, change int) string {
	loc := locales[locale]
	symbol := currencySymbols[currency]
	negative := change < 0
	cents := abs(change)
	units := strconv.Itoa(cents / 100)
	frac := strconv.Itoa(cents % 100)
	grouped := groupDigits(units, loc.groupSep)

